), c as (
  select id from accounting.companies where name='akmic合同会社' order by created_at limit 1
), fy as (
  select f.id
  from accounting.fiscal_years f cross join c
  where f.company_id=c.id and f.start_date='2021-11-01' and f.end_date='2022-10-31'
)
insert into accounting.journals
(company_id,fiscal_year_id,entry_date,voucher_no,description,memo,status,source_system,source_record_id,source_data,entry_kind)
select c.id,fy.id,src.entry_date,src.voucher_no,src.description,src.memo,'draft','moneyforward',
       src.source_record_id,src.source_data,src.entry_kind
from src cross join c cross join fy
on conflict (company_id,source_system,source_record_id) where source_record_id is not null
do nothing;


