('voMO2f5TH3mfDsKyQlbUT8MyVrtWIjfAQ5gHXBnrB4o%3D',1,'credit','gbcbEGfWvMItnKlt%2FOZoyA%3D%3D',null,70000,'県民税20,000円、市民税50,000円',null,null,null)
), c as (
  select id from accounting.companies where name='akmic合同会社' order by created_at limit 1
), fy as (
  select f.id
  from accounting.fiscal_years f cross join c
  where f.company_id=c.id and f.start_date='2021-11-01' and f.end_date='2022-10-31'
)
insert into accounting.journal_lines
(journal_id,line_no,account_id,sub_account_id,side,amount,memo,department,tax_name,partner_name)
select
  j.id,src.line_no,a.id,sa.id,src.side,src.amount,src.memo,src.department,src.tax_name,src.partner_name
from src
cross join c cross join fy
join accounting.journals j
  on j.company_id=c.id and j.fiscal_year_id=fy.id
 and j.source_system='moneyforward' and j.source_record_id=src.journal_source_record_id
join accounting.accounts a
  on a.company_id=c.id and a.source_system='moneyforward'
 and a.source_record_id=src.account_source_record_id
left join accounting.sub_accounts sa
  on sa.company_id=c.id and sa.source_system='moneyforward'
 and sa.source_record_id=src.sub_account_source_record_id
where j.status='draft'
  and not exists (
    select 1 from accounting.journal_lines jl
    where jl.journal_id=j.id and jl.line_no=src.line_no and jl.side=src.side
  );


do $$
declare
  v_company_id uuid;
  v_fiscal_year_id uuid;
  v_journals integer;
  v_lines integer;
  v_debit numeric;
  v_credit numeric;
  v_unbalanced integer;
  v_opening integer;
  v_adjusting integer;
  v_regular integer;
begin
  select id into v_company_id
  from accounting.companies where name='akmic合同会社' order by created_at limit 1;

  select id into v_fiscal_year_id
  from accounting.fiscal_years
  where company_id=v_company_id and start_date='2021-11-01' and end_date='2022-10-31';

  select count(*),
         count(*) filter (where entry_kind='opening'),
         count(*) filter (where entry_kind='adjusting'),
         count(*) filter (where entry_kind='regular')
    into v_journals,v_opening,v_adjusting,v_regular
  from accounting.journals
  where company_id=v_company_id and fiscal_year_id=v_fiscal_year_id and source_system='moneyforward';

  select count(*),
         coalesce(sum(jl.amount) filter (where jl.side='debit'),0),
         coalesce(sum(jl.amount) filter (where jl.side='credit'),0)
    into v_lines,v_debit,v_credit
  from accounting.journal_lines jl
  join accounting.journals j on j.id=jl.journal_id
  where j.company_id=v_company_id and j.fiscal_year_id=v_fiscal_year_id and j.source_system='moneyforward';

  select count(*) into v_unbalanced
  from accounting.journals j
  where j.company_id=v_company_id and j.fiscal_year_id=v_fiscal_year_id
    and j.source_system='moneyforward'
    and j.total_debit <> j.total_credit;

  if v_journals <> 303 then raise exception 'Expected 303 journals, got %',v_journals; end if;
  if v_lines <> 682 then raise exception 'Expected 682 lines, got %',v_lines; end if;
  if v_debit <> 19184985 then raise exception 'Expected debit 19184985, got %',v_debit; end if;
  if v_credit <> 19184985 then raise exception 'Expected credit 19184985, got %',v_credit; end if;
  if v_unbalanced <> 0 then raise exception 'Expected 0 unbalanced journals, got %',v_unbalanced; end if;
  if v_opening <> 0 or v_adjusting <> 4 or v_regular <> 299 then
    raise exception 'entry_kind mismatch opening %, adjusting %, regular %',v_opening,v_adjusting,v_regular;
  end if;

  update accounting.journals
     set status='posted'
   where company_id=v_company_id and fiscal_year_id=v_fiscal_year_id
     and source_system='moneyforward' and status='draft';
end $$;

commit;
